-- Name: ballots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ballots (
    id text NOT NULL,
    judge_participant_id text NOT NULL,
    rubric_version text NOT NULL,
    winner text,
    scores jsonb,
    reason text,
    feedback jsonb,
    citations jsonb,
    submitted_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    round_id text NOT NULL,
    freeze_revision integer NOT NULL,
    ballot_definition_id text,
    ballot_definition_version integer,
    decision text DEFAULT 'win'::text NOT NULL,
    ranking jsonb,
    speaker_ranks jsonb,
    CONSTRAINT ballots_ballot_definition_complete CHECK (((ballot_definition_id IS NULL) = (ballot_definition_version IS NULL))),
    CONSTRAINT ballots_citations_is_object CHECK ((jsonb_typeof(citations) = 'object'::text)),
    CONSTRAINT ballots_daisy_definition_check CHECK (((ballot_definition_id IS NOT NULL) OR (rubric_version = ANY (ARRAY['speaker-10@1'::text, 'speaker-10@2'::text, 'rank-sides@1'::text, 'rank-speakers@1'::text])))),
    CONSTRAINT ballots_decision_check CHECK ((decision = ANY (ARRAY['win'::text, 'tie'::text, 'double_loss'::text, 'ranking'::text]))),
    CONSTRAINT ballots_feedback_is_object CHECK ((jsonb_typeof(feedback) = 'object'::text)),
    CONSTRAINT ballots_freeze_revision_positive CHECK ((freeze_revision > 0)),
    CONSTRAINT ballots_ranking_check CHECK ((((ranking IS NOT NULL) = (decision = 'ranking'::text)) AND ((ranking IS NULL) OR (jsonb_typeof(ranking) = 'array'::text)))),
    CONSTRAINT ballots_rubric_version_check CHECK ((rubric_version ~ '^[a-z][a-z0-9-]{0,39}@[1-9][0-9]*$'::text)),
    CONSTRAINT ballots_scores_is_object CHECK ((jsonb_typeof(scores) = 'object'::text)),
    CONSTRAINT ballots_speaker_ranks_check CHECK (((speaker_ranks IS NULL) OR ((jsonb_typeof(speaker_ranks) = 'array'::text) AND (jsonb_array_length(speaker_ranks) > 0) AND (NOT jsonb_path_exists(speaker_ranks, 'strict $[*]?(@.type() != "array" || @.size() == 0)'::jsonpath)) AND (NOT jsonb_path_exists(speaker_ranks, 'strict $[*][*]?(@.type() != "string")'::jsonpath))))),
    CONSTRAINT ballots_winner_check CHECK ((((winner IS NOT NULL) = (decision = 'win'::text)) AND ((winner IS NULL) OR ((winner ~ '^[a-z][a-z_]{0,23}$'::text) AND (winner <> ALL (ARRAY['side'::text, 'speaker'::text, 'judge'::text, 'moderator'::text]))))))
);


