-- Name: daisy_debater_was_under_18(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.daisy_debater_was_under_18(requested_user_id text, as_of timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.account_age age
    WHERE age.user_id=requested_user_id
      AND public.daisy_age_band(age.birth_month, age.version, least(age.recorded_at, as_of), as_of)
        IN ('under-13', '13-15', '16-17'))
$$;


