CREATE FUNCTION public.daisy_dm_request_access(recipient_id text, requester_actor_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
