--
-- Name: daisy_prune_read_notifications(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.daisy_prune_read_notifications(cutoff timestamp with time zone, batch_size integer) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  WITH expired AS (
    SELECT id FROM public.notifications
    WHERE isfinite(cutoff) AND batch_size BETWEEN 1 AND 500
      AND read_at < cutoff AND (kind <> 'friend_guardian_approval'
        OR read_at < statement_timestamp() - interval '90 days')
    ORDER BY read_at, id LIMIT greatest(0, least(500, coalesce(batch_size, 0)))
    FOR UPDATE SKIP LOCKED
  ), removed AS (
    DELETE FROM public.notifications notice
    USING expired WHERE notice.id = expired.id RETURNING 1
  ) SELECT count(*)::integer FROM removed
$$;


--> statement-breakpoint
--
-- Name: daisy_purge_flag_evidence(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.daisy_purge_flag_evidence(before_time timestamp with time zone, batch_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE ids text[]; removed integer;
BEGIN
  IF batch_limit IS NULL OR batch_limit < 1 OR batch_limit > 500 OR before_time IS NULL THEN
    RAISE EXCEPTION 'invalid retention bound' USING ERRCODE = '23514';
  END IF;
  PERFORM pg_advisory_xact_lock(59118, 1);
  SELECT array_agg(command_id) INTO ids FROM (
    SELECT command_id FROM public.operator_command_receipts
    WHERE action IN ('flag.state.update', 'flag.override.update')
      AND created_at <= least(before_time, clock_timestamp() - interval '90 days')
    ORDER BY created_at, command_id LIMIT batch_limit
  ) due;
  DELETE FROM public.flag_change_events WHERE command_id = ANY(ids);
  DELETE FROM public.operator_command_receipts WHERE command_id = ANY(ids);
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;
$$;


