--
-- Name: formats_assert_current_preset(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.formats_assert_current_preset(target text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "formats" f
    WHERE f."id" = target
      AND f."catalog_role" IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM "format_presets" p
        WHERE p."format_id" = f."id"
          AND p."format_version" = f."current_version"
          AND p."superseded_at" IS NULL
      )
  ) THEN
    RAISE EXCEPTION 'A catalog format needs a current preset at its current revision'
      USING ERRCODE = '23514', CONSTRAINT = 'formats_current_preset_present';
  END IF;
END
$$;


--> statement-breakpoint
--
-- Name: formats_current_preset_present(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.formats_current_preset_present() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'formats' THEN
    PERFORM formats_assert_current_preset(NEW."id");
  ELSE
    IF TG_OP <> 'INSERT' THEN
      PERFORM formats_assert_current_preset(OLD."format_id");
    END IF;
    IF TG_OP <> 'DELETE' THEN
      PERFORM formats_assert_current_preset(NEW."format_id");
    END IF;
  END IF;
  RETURN NULL;
END
$$;


