    CONSTRAINT rooms_league_ladder_is_casual_standing CHECK (((league_ladder_id IS NULL) OR ((lobby_kind = 'standing'::text) AND (competition_type = 'casual'::text)))),
    CONSTRAINT rooms_legacy_tournament_youth_check CHECK (((legacy_tournament_youth IS NULL) OR (lobby_kind = 'tournament'::text))),
    CONSTRAINT rooms_ranked_has_preset_check CHECK (((competition_type = 'ranked'::text) = (preset_version IS NOT NULL))),
    CONSTRAINT rooms_ranked_public_check CHECK (((competition_type <> 'ranked'::text) OR (visibility = 'public'::text))),
