    CONSTRAINT usage_reservations_binding_check CHECK ((((NOT binds_free_judge) OR ((kind = 'ai_round'::text) AND ((source ->> 'kind'::text) = 'lifetime'::text))) AND ((binding_released_at IS NULL) OR (binds_free_judge AND ((state ->> 'kind'::text) = 'released'::text) AND (binding_released_at >= reserved_at))))),
    CONSTRAINT usage_reservations_count_check CHECK (COALESCE(
CASE
    WHEN ((state ->> 'kind'::text) = ANY (ARRAY['reserved'::text, 'released'::text])) THEN (NOT (state ?| ARRAY['countedAt'::text, 'countBasis'::text]))
    ELSE (((state ->> 'countBasis'::text) = ANY (ARRAY['dispatch_record'::text, 'historical_observation'::text])) AND (jsonb_typeof((state -> 'countedAt'::text)) = 'string'::text) AND isfinite(((state ->> 'countedAt'::text))::timestamp with time zone) AND (((state ->> 'countedAt'::text))::timestamp with time zone >= reserved_at) AND (((state ->> 'countedAt'::text))::timestamp with time zone <= clock_timestamp()))
END, false)),
    CONSTRAINT usage_reservations_kind_check CHECK ((kind = ANY (ARRAY['ai_round'::text, 'casual_ai_judge'::text, 'round_analysis'::text]))),
    CONSTRAINT usage_reservations_reserved_at_check CHECK (isfinite(reserved_at)),
    CONSTRAINT usage_reservations_source_check CHECK ((COALESCE(
CASE (source ->> 'kind'::text)
    WHEN 'lifetime'::text THEN (source = '{"kind": "lifetime"}'::jsonb)
    WHEN 'beta'::text THEN ((source - ARRAY['kind'::text, 'startsAt'::text, 'endsAt'::text]) = '{}'::jsonb)
    WHEN 'subscription'::text THEN (((source - ARRAY['kind'::text, 'subscriptionId'::text, 'startsAt'::text, 'endsAt'::text]) = '{}'::jsonb) AND ((source ->> 'subscriptionId'::text) ~ '^[a-z][a-z0-9]{23}$'::text))
    WHEN 'organization_seat'::text THEN (((source - ARRAY['kind'::text, 'organizationId'::text, 'startsAt'::text, 'endsAt'::text]) = '{}'::jsonb) AND ((source ->> 'organizationId'::text) ~ '^[a-z0-9]{24}$'::text))
    ELSE false
END, false) AND COALESCE((((source ->> 'kind'::text) = 'lifetime'::text) OR ((jsonb_typeof((source -> 'startsAt'::text)) = 'string'::text) AND (jsonb_typeof((source -> 'endsAt'::text)) = 'string'::text) AND isfinite(((source ->> 'startsAt'::text))::timestamp with time zone) AND isfinite(((source ->> 'endsAt'::text))::timestamp with time zone) AND (((source ->> 'startsAt'::text))::timestamp with time zone < ((source ->> 'endsAt'::text))::timestamp with time zone))), false))),
    CONSTRAINT usage_reservations_source_is_object CHECK ((jsonb_typeof(source) = 'object'::text)),
    CONSTRAINT usage_reservations_state_check CHECK (COALESCE(
CASE (state ->> 'kind'::text)
    WHEN 'reserved'::text THEN (state = '{"kind": "reserved"}'::jsonb)
    WHEN 'released'::text THEN (((state - ARRAY['kind'::text, 'releasedAt'::text]) = '{}'::jsonb) AND (jsonb_typeof((state -> 'releasedAt'::text)) = 'string'::text) AND isfinite(((state ->> 'releasedAt'::text))::timestamp with time zone) AND (((state ->> 'releasedAt'::text))::timestamp with time zone >= reserved_at))
    WHEN 'dispatched'::text THEN ((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text]) = '{}'::jsonb)
    WHEN 'unknown'::text THEN ((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text]) = '{}'::jsonb)
    WHEN 'delivered'::text THEN ((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text]) = '{}'::jsonb)
    WHEN 'definite_failure'::text THEN ((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text]) = '{}'::jsonb)
    WHEN 'refunded'::text THEN (((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text, 'refundedAt'::text]) = '{}'::jsonb) AND (jsonb_typeof((state -> 'refundedAt'::text)) = 'string'::text) AND isfinite(((state ->> 'refundedAt'::text))::timestamp with time zone) AND (((state ->> 'refundedAt'::text))::timestamp with time zone >= ((state ->> 'countedAt'::text))::timestamp with time zone))
    WHEN 'credited'::text THEN ((kind = 'ai_round'::text) AND ((state - ARRAY['kind'::text, 'countedAt'::text, 'countBasis'::text, 'creditedAt'::text, 'provenance'::text, 'providerOutcome'::text]) = '{}'::jsonb) AND (jsonb_typeof((state -> 'creditedAt'::text)) = 'string'::text) AND isfinite(((state ->> 'creditedAt'::text))::timestamp with time zone) AND (((state ->> 'creditedAt'::text))::timestamp with time zone >= ((state ->> 'countedAt'::text))::timestamp with time zone) AND ((state ->> 'providerOutcome'::text) = ANY (ARRAY['dispatched'::text, 'unknown'::text, 'delivered'::text, 'definite_failure'::text])) AND (jsonb_typeof((state -> 'provenance'::text)) = 'object'::text) AND
    CASE ((state -> 'provenance'::text) ->> 'kind'::text)
        WHEN 'recorded_restoration'::text THEN ((state -> 'provenance'::text) = '{"kind": "recorded_restoration"}'::jsonb)
        WHEN 'recovery_bound'::text THEN ((((state -> 'provenance'::text) - ARRAY['kind'::text, 'incidentId'::text]) = '{}'::jsonb) AND (((state -> 'provenance'::text) ->> 'incidentId'::text) ~ '^[a-z][a-z0-9]{23}$'::text))
        WHEN 'capture_shortfall'::text THEN ((((state -> 'provenance'::text) - ARRAY['kind'::text, 'commandId'::text, 'freezeRevision'::text]) = '{}'::jsonb) AND (((state -> 'provenance'::text) ->> 'commandId'::text) ~ '^[a-z][a-z0-9]{23}$'::text) AND (jsonb_typeof(((state -> 'provenance'::text) -> 'freezeRevision'::text)) = 'number'::text) AND (((state -> 'provenance'::text) ->> 'freezeRevision'::text) ~ '^[1-9][0-9]*$'::text))
        ELSE false
    END)
    ELSE false
END, false)),
    CONSTRAINT usage_reservations_state_is_object CHECK ((jsonb_typeof(state) = 'object'::text))
);


